// [A] 초기 목록 미해결 — jldinf10901: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10901.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_dataList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_dataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_dataList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_dataList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: clickRadio('${row.basIsuNm}','${row.basIsuAbbrv}','${row.basIsuEngNm}','${row.basIsuEngAbbrv}');focus_tr(this); (EL 미해석) */
        if (typeof scwin.clickRadio === 'function') { scwin.clickRadio(r["basIsuNm"], r["basIsuAbbrv"], r["basIsuEngNm"], r["basIsuEngAbbrv"]); } else { console.error('[sdd] 행 동작 미정의: scwin.clickRadio (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.clickRadio'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_dataList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.ipt_korNm_onkeydown
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_korNm_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_korNm_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ await scwin.send_form() }
        fn_engNumNotSpecCheck(selfVar);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10901.ipt_korNm_onkeydown' }); }
};

/**
 * @event
 * @name scwin.btn_sendForm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_sendForm_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_sendForm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.send_form()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10901.btn_sendForm_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_winClose_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_winClose_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_winClose_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.win_close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10901.btn_winClose_onclick' }); }
};


