/**
 * @method
 * @name scwin.send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.send_form = async function () {
    /* sdd-asis-lifecycle:begin send_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let korNm = $c.util.getComponent('ipt_korNm').getValue(); if (korNm == null) { korNm = ''; }
    if (korNm === '') {
        await $c.win.alert("고유명을 입력해 주세요");
        ($c.util.getComponent('ipt_korNm') && $c.util.getComponent('ipt_korNm').setFocus ? $c.util.getComponent('ipt_korNm').setFocus() : ($c.util.getComponent('ipt_korNm') && $c.util.getComponent('ipt_korNm').focus ? $c.util.getComponent('ipt_korNm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_korNm')));
        return;
    }
    const ckRadio = $('input[type=radio]:checked').length;
    if (ckRadio == 0) {
        await $c.win.alert("기준명을 선택해 주세요.");
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_korNm').getValue()) > 20) {
        await $c.win.alert("고유명을 20자 이내로 입력하세요.");
        $('#ipt_korNm').select();
        return;
    }
    scwin.chkDuple();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkDuple
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkDuple = function () {
    /* sdd-asis-lifecycle:begin fn_ChkDuple — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF10901 || { elements: [] });
    const url = "/stdcd/bond.do?method=searchElsdlsIsuNm";
    const isur_cd = (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})["isur_cd"] && (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})["isur_cd"]).getValue ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})["isur_cd"]).getValue() : (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("isur_cd") || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("isur_cd").getValue() : ''));
    const params = "isur_cd=" + isur_cd + "&isu_nm=" + $c.util.getComponent('ipt_isuNm').getValue() + "&unq_isu_nm=" + $c.util.getComponent('ipt_korNm').getValue();
    $.post(url, params, async function(obj) {
            if (obj === '') {
                let korNm = $c.util.getComponent('ipt_korNm').getValue(); if (korNm == null) { korNm = ''; }
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("v_isu_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuNm').getValue() + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("v_isu_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuAbbrNm") + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("v_isu_eng_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuEngNm').getValue() + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("v_isu_eng_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuEndAbbrNm") + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("isu_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuNm').getValue());
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("isu_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuAbbrNm"));
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("isu_eng_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuEngNm').getValue());
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("isu_eng_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuEndAbbrNm"));
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("std_isu_cd")) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("std_isu_cd")).setValue ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("std_isu_cd")).setValue(korNm) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "std_isu_cd"), void (korNm)));
                $c.win.closePopup();
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                let strMsg = "표준코드 : " + jsonData.std_cd + "\n" + "종목명 : " + jsonData.isu_nm + " " + jsonData.unq_isu_nm + "\n\n";
                strMsg = "이미 등록된 종목명 입니다.";
                await $c.win.alert(strMsg);
                return false;
            }
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.win_close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.win_close = function () {
    /* sdd-asis-lifecycle:begin win_close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clickRadio
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_isuNm ipt_isuAbbrNm ipt_isuEngNm ipt_isuEndAbbrNm
 * @returns
 * @hidden N
*/
scwin.clickRadio = function (ipt_isuNm, ipt_isuAbbrNm, ipt_isuEngNm, ipt_isuEndAbbrNm) {
    /* sdd-asis-lifecycle:begin clickRadio — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_isuNm').setValue(ipt_isuNm);
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isuAbbrNm', ipt_isuAbbrNm) : console.warn('[sdd] hiddenStore 부재: ipt_isuAbbrNm'));
    $c.util.getComponent('ipt_isuEngNm').setValue(ipt_isuEngNm);
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isuEndAbbrNm', ipt_isuEndAbbrNm) : console.warn('[sdd] hiddenStore 부재: ipt_isuEndAbbrNm'));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.focus_tr
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.focus_tr = function (obj) {
    /* sdd-asis-lifecycle:begin focus_tr — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const radio = document.getElementsByName("ipt_isuList");
    let i;
    const tabNum = obj.parentNode.children.length;
    for (i = 0; i < tabNum; i++) {
        obj.parentNode.children[i].className = '';
        radio[i].checked = false;
    }
    obj.className = 'on';
    radio[obj.rowIndex -1].checked = true;
    /* sdd-asis-lifecycle:end */
};
